<script lang="ts">
 import {untrack} from 'svelte';import Modal from './Modal.svelte';import Feedback from './Feedback.svelte';import {Button} from '#lib/components/ui/button/index.ts';import {adminUsersApi} from '#lib/api/admin/users.ts';import {requiresFacility} from '#lib/auth/roles.ts';import {apiMessage} from '#lib/admin/scheduling.ts';import type {AdminUser,Role} from '#lib/types/user.ts';import type {MedicalFacility} from '#lib/types/clinic.ts';
 let {open=$bindable(false),user=null,roles,facilities,onSaved}:{open?:boolean;user?:AdminUser|null;roles:Role[];facilities:MedicalFacility[];onSaved:()=>void}=$props();let email=$state(''),phone=$state(''),password=$state(''),facility=$state(''),active=$state(true),chosen=$state<string[]>([]),busy=$state(false),error=$state(''),createdId=$state<string|null>(null);
 $effect(()=>{if(!open)return;const u=user;untrack(()=>{email=u?.email??'';phone=u?.phone_number??'';password='';facility=u?.facility_id??'';active=u?.is_active??true;chosen=[];createdId=null;error='';});});
 async function save(e:SubmitEvent){e.preventDefault();error='';const bound=user?user.roles.some(requiresFacility):roles.some(r=>chosen.includes(r.id)&&requiresFacility(r.name));if(bound&&!facility){error='院所角色必須選擇所屬院所';return;}if(!user&&!chosen.length){error='請選擇至少一個員工角色';return;}busy=true;try{if(!user&&!createdId){const created=await adminUsersApi.create({email:email.trim(),password,phone_number:phone.trim()||undefined});createdId=created.id;password='';}
 const id=user?.id??createdId!;await adminUsersApi.update(id,{email:email.trim(),phone_number:phone.trim()||null,facility_id:facility||null,is_active:active});if(!user)await adminUsersApi.setUserRoles(id,chosen);onSaved();open=false;}catch(e){error=(createdId?'帳號已建立，剩餘設定尚未完成。按「繼續完成設定」重試，不會重複建立帳號。 ':'')+apiMessage(e,'帳號儲存失敗');if(createdId)onSaved();}finally{busy=false;}}
</script>
<Modal bind:open title={user?'編輯帳號':'新增員工帳號'} description="院所管理員與員工必須綁定所屬院所。" {busy}><form onsubmit={save} class="space-y-4"><Feedback {error}/><fieldset disabled={busy} class="space-y-4"><label>電子郵件<input type="email" bind:value={email} disabled={!!createdId} required autocomplete="off"/></label>{#if !user&&!createdId}<label>初始密碼<input type="password" bind:value={password} minlength="8" autocomplete="new-password" required/></label>{/if}<label>聯絡電話<input type="tel" bind:value={phone}/></label><label>所屬院所<select aria-label="所屬院所" bind:value={facility}><option value="">未綁定院所</option>{#each facilities as f (f.id)}<option value={f.id}>{f.name}</option>{/each}</select></label>{#if !user}<fieldset class="space-y-3"><legend>員工角色</legend>{#each roles as r (r.id)}<label><input type="checkbox" value={r.id} bind:group={chosen}/>{r.display_name}</label>{/each}</fieldset>{/if}<label><input type="checkbox" bind:checked={active}/>啟用帳號</label></fieldset><div class="flex justify-end gap-2"><Button variant="outline" disabled={busy} onclick={()=>{if(createdId)onSaved();open=false;}}>取消</Button><Button type="submit" disabled={busy}>{createdId?'繼續完成設定':'儲存帳號'}</Button></div></form></Modal>
